    // Implement closure counter
}

exercises.solutionCode:
function createCounter(initialValue = 0) {
    let count = initialValue;

    return {
        increment: () => ++count,
        decrement: () => --count,
        getValue: () => count
    };
}

const counter = createCounter(10);
counter.increment();
counter.increment();
console.log(`Current Count: ${counter.getValue()}`); // 12

