class EventEmitter {
    // Implement pub/sub pattern
}

exercises.solutionCode:
class EventEmitter {
    constructor() {
        this.events = {};
    }

    on(event, listener) {
        if (!this.events[event]) this.events[event] = [];
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

const emitter = new EventEmitter();
emitter.on('userLogin', user => console.log(`Logged in: ${user.name}`));
emitter.emit('userLogin', { name: 'Alex' });

