exercises.solutionCode:
class ExpenseTracker {
    constructor() {
        this.transactions = JSON.parse(localStorage.getItem('txs')) || [];
    }

    addTransaction(text, amount) {
        const tx = {
            id: Date.now(),
            text,
            amount: parseFloat(amount)
        };
        this.transactions.push(tx);
        this.save();
        return tx;
    }

    getBalance() {
        return this.transactions.reduce((sum, tx) => sum + tx.amount, 0);
    }

    getIncome() {
        return this.transactions
            .filter(tx => tx.amount > 0)
            .reduce((sum, tx) => sum + tx.amount, 0);
    }

    getExpenses() {
        return this.transactions
            .filter(tx => tx.amount < 0)
            .reduce((sum, tx) => sum + tx.amount, 0);
    }

    save() {
        localStorage.setItem('txs', JSON.stringify(this.transactions));
    }
}

const tracker = new ExpenseTracker();
tracker.addTransaction('Salary', 2500);
tracker.addTransaction('Server Hosting', -50);
console.log(`Balance: $${tracker.getBalance()}, Income: $${tracker.getIncome()}, Expenses: $${tracker.getExpenses()}`);
